def retrieve_context(question,context):
 import re,math
 lines=context.splitlines()
 if not lines or any(':' not in line for line in lines): return context
 titles=[line.split(':',1)[0] for line in lines]
 docs={title:'\n'.join(line for line,t in zip(lines,titles) if t==title) for title in dict.fromkeys(titles)}
 stop={'a','an','the','of','and','or','is','are','were','was','what','which','who','in','as','to','have','has','do','did','does','for','by','with','it','its','from','that','this','on','at','be'}
 def words(s): return {w.rstrip('s') for w in re.findall('[a-z]+',s.lower()) if w not in stop}
 query=words(question); terms={t:words(text) for t,text in docs.items()}
 scores={t:sum(math.log(1+len(docs)/(1+sum(w in other for other in terms.values()))) for w in query&tokens) for t,tokens in terms.items()}
 best=max(scores.values())
 if best<=0: return context
 chosen={t for t,s in scores.items() if abs(s-best)<1e-9}
 while True:
  linked={t for t in docs if any(t.casefold() in docs[c].casefold() for c in chosen)}
  if linked<=chosen: break
  chosen|=linked
 return '\n'.join(line for line,t in zip(lines,titles) if t in chosen)

